import{r as e}from"./rolldown-runtime-XKyaHtl9.js";import{i as t,r as n}from"./vendor-framer-HPtay4w-.js";import{u as r}from"./index-Dy_4qWHW.js";import{t as i}from"./verses-Egs9pT8l.js";import{t as a}from"./VerseCard-DlpPiVpU.js";import{t as o}from"./FullWidthVerseBand-k2qLPXXo.js";import{t as s}from"./UpanishadPageShell-D1UipKqM.js";var c=e(t(),1),l={id:13,devanagariNumeral:`१३`,title:`Action Without Collapse: Engaged Non-Attachment`,subtitle:`The Īśā Vision of Joyful Longevity & Dynamic Presence`,sanskritTitle:`कुर्वन्नेवेह कर्माणि जिजीविषेच्छतं समाः`,epigraph:`तेन त्यक्तेन भुञ्जीथा मा गृधः कस्यस्विद्धनम् — Rejoice through letting go; do not covet the wealth of anyone.`,content:[{type:`prose`,text:`A frequent mischaracterization of Indian philosophy—circulated by early colonial commentators such as Hegel and later repeated in casual literature—is that the Upaniṣads advocate world-negating escapism, passive quietism, or life-denying fatalism. The opening verses of the Īśā Upaniṣad decisively refute this misconception. Embedded directly within the Śukla Yajurveda Saṃhitā, the Īśā begins not with an injunction to flee the world into forest hermitages, but with a magnificent ecological and psychological manifesto: 'īśāvāsyam idaṃ sarvaṃ yat kiñca jagatyāṃ jagat'—All this, whatever moves and fluctuates in this changing cosmos, is enveloped by sacred awareness.`},{type:`verse_ref`,verseId:`isha-1`},{type:`prose`,text:`From this cosmological vision follows a paradoxical psychological injunction: 'tena tyaktena bhuñjīthāḥ'—enjoy life through letting go; rejoice through non-attachment. The Upaniṣadic seer recognizes that toxic possessiveness is the enemy of genuine enjoyment. When we attempt to possess a person, an achievement, or a status object, our enjoyment is immediately infected by anxiety over its eventual decay or loss. By renouncing possessive clinging (tyāga), we are liberated to experience the beauty of the world with unburdened presence. Renunciation here is not ascetic deprivation; it is the prerequisite for pristine delight.`},{type:`prose`,text:`The very next verse delivers an unapologetic affirmation of human vitality, social responsibility, and longevity: 'kurvann eveha karmāṇi jijīviṣec chataṃ samāḥ'—performing dedicated work in this world, let a person desire to live a full hundred years! The text insists that action (karma) performed without egoistic clinging does not contaminate or exhaust the human soul ('na karma lipyate nare'). Dynamic engagement and inner serenity are not mutually exclusive poles; they are mutually reinforcing partners.`},{type:`verse_ref`,verseId:`isha-2`},{type:`prose`,text:`This Īśā vision serves as the canonical foundation for the later formulation of Karma Yoga in the Bhagavad Gītā (specifically chapter 2, verses 47–55). In the famous dialogue of the battlefield, Kṛṣṇa synthesizes the Īśā doctrine into the portrait of the Sthitaprajña—the person of unshakable wisdom who acts decisively in the midst of extreme crisis without psychological collapse, having surrendered anxious attachment to outcomes (phala-tṛṣṇā). The Gītā, while traditionally categorized as Smṛti (remembered tradition), is revered as the distilled nectar of the Upaniṣadic cows ('sarvopaniṣado gāvo dogdhā gopāla-nandanaḥ').`},{type:`resilience_insight`,title:`The Cure for Burnout`,text:`Modern occupational burnout rarely stems from hard work alone; it stems from toxic outcome-fixation, hyper-vigilance over personal credit, and the frantic terror of failure. The Īśā formula—acting wholeheartedly while releasing possessive clinging—decouples professional effort from existential terror. Work ceases to be a frantic defense of ego-worth and becomes a joyful expression of purposeful energy.`},{type:`modern_parallel`,title:`Intrinsically Motivated Flow vs Extrinsic Anxiety`,text:`Parallels Self-Determination Theory (Deci & Ryan, 2000) and Mihaly Csíkszentmihályi's flow research (1990). When individuals are extrinsically motivated by outcome-control, ego threat remains perpetually elevated, depleting executive resilience. Conversely, intrinsic task absorption and non-attachment to external reward cultivate durable psychological longevity and high distress tolerance.`},{type:`reflect`,prompt:`Think of an ongoing project or responsibility that feels heavy. What would it look like to perform the necessary actions with total dedication, while completely letting go of the need to control how others respond to the outcome?`}],sources:[`Īśā Upaniṣad verses 1–3`,`Śaṅkara's Bhāṣya on Īśā Upaniṣad`,`Mahatma Gandhi, Speech on Īśā Upaniṣad at Kottayam (1937)`,`B.G. Tilak, Śrīmad Bhagavadgītā Rahasya (1915)`,`Patrick Olivelle, The Early Upaniṣads (1998)`],wordCount:750},u=n(),d=new Map;i.forEach(e=>d.set(e.id,e));var f=r.find(e=>e.slug===`isha`),p=r.find(e=>e.slug===`kena`),m=[{id:`purnam`,label:`Wholeness (Pūrṇam)`},{id:`verse1`,label:`Enveloping All (v. 1)`},{id:`action`,label:`100-Year Engagement (v. 2)`},{id:`unity`,label:`Beyond Sorrow (v. 7)`},{id:`vidya`,label:`Vidyā & Avidyā`}];function h(){let[e,t]=(0,c.useState)(`purnam`),n=d.get(`isha-shanti-purnam`),r=d.get(`isha-1`),i=d.get(`isha-2`),h=d.get(`isha-7`);return(0,u.jsxs)(s,{meta:f,prev:{title:`The Corpus & Sages`,path:`/corpus`,devanagari:`वाङ्मयम्`},next:{title:p.title,path:p.path,devanagari:p.devanagari,teaser:p.teaser},steps:m,activeStep:e,onStepChange:t,resilienceInsight:{title:`Engaged Non-Attachment: The Armor of Tena Tyaktena`,text:`The Īśā Upaniṣad resolves the ancient paradox between quietism and burn-out. You do not withdraw from the world to stay pure, nor do you grasp at outcomes with panic. You enjoy the world through renouncing possessiveness (*tena tyaktena bhuñjīthāḥ*). This is the psychological root of anti-fragile action.`},modernParallel:{title:`Locus of Control & Process Orientation`,text:`Contemporary cognitive psychology recognizes that psychological distress stems largely from conflating effort (within control) with outcomes (outside control). The Īśā anticipates this 2,500 years earlier: act with full vitality for a hundred years, yet maintain absolute internal detachment from possessive clinging.`},reflectPrompt:`What would your daily work feel like if you saw every situation as already enveloped by sacred presence, requiring your full effort but zero clutching?`,sources:l.sources,commentaryDrawer:{title:`Śaṅkara on Īśāvāsyopaniṣad: Renunciation as the Foundation of Fearless Living`,content:(0,u.jsxs)(u.Fragment,{children:[(0,u.jsx)(`p`,{children:`In his preamble to the Īśāvāsya Bhāṣya, Ādi Śaṅkara notes that the first verse sets forth the highest knowledge for the steadfast contemplative: recognizing that whatever moves in this moving world is cloaked in the Supreme Lord. By abandoning the false attribution of independent reality to transient objects, one protects oneself from covetousness.`}),(0,u.jsx)(`p`,{children:`Verse 2 addresses those who are engaged in active life: "Only by performing works here should one desire to live a hundred years." Action performed with a sacrificial ethos does not bind the actor. In verse 7, Śaṅkara explains that when one sees all beings as the Self, where can there be grief or delusion? Grief (*śoka*) and delusion (*moha*) are born exclusively from perceived separation.`})]})},children:[(0,u.jsxs)(`section`,{id:`purnam`,className:`w-full max-w-[1000px] mx-auto space-y-8 flex flex-col items-center`,children:[(0,u.jsxs)(`div`,{className:`w-full p-8 sm:p-10 rounded-[20px] bg-[var(--surface)] border border-[var(--border-color)] shadow-sm text-center space-y-4`,children:[(0,u.jsx)(`span`,{className:`text-xs sm:text-sm uppercase tracking-widest text-[var(--gold)] font-[var(--font-marginalia)] font-bold block`,children:`१.१ · शान्तिपाठः`}),(0,u.jsx)(`h2`,{className:`font-[var(--font-heading-alt)] font-semibold text-[var(--text-primary)] text-balance mx-auto`,style:{fontSize:`clamp(1.75rem, 3.5vw, 2.75rem)`,lineHeight:1.2},children:`The Axiom of Undivided Wholeness`}),(0,u.jsx)(`div`,{className:`w-full max-w-[68ch] mx-auto text-left`,children:(0,u.jsx)(`p`,{className:`text-[var(--text-secondary)] leading-relaxed`,style:{fontSize:`clamp(1.05rem, 1.25vw, 1.25rem)`,lineHeight:1.75},children:`The Īśā opens not with an apology for human weakness, but with a mathematical paradox of consciousness: That is whole, this is whole; from wholeness comes wholeness; when wholeness is taken from wholeness, wholeness remains.`})})]}),n&&(0,u.jsx)(o,{verse:n})]}),(0,u.jsxs)(`section`,{id:`verse1`,className:`w-full max-w-[1000px] mx-auto space-y-8 flex flex-col items-center`,children:[(0,u.jsxs)(`div`,{className:`w-full p-8 sm:p-10 rounded-[20px] bg-[var(--surface)] border border-[var(--border-color)] shadow-sm text-center space-y-4`,children:[(0,u.jsx)(`span`,{className:`text-xs sm:text-sm uppercase tracking-widest text-[var(--gold)] font-[var(--font-marginalia)] font-bold block`,children:`१.२ · ईशावास्यम्`}),(0,u.jsx)(`h2`,{className:`font-[var(--font-heading-alt)] font-semibold text-[var(--text-primary)] text-balance mx-auto`,style:{fontSize:`clamp(1.75rem, 3.5vw, 2.75rem)`,lineHeight:1.2},children:`Enveloping the World in Presence`}),(0,u.jsxs)(`div`,{className:`w-full max-w-[68ch] mx-auto text-left space-y-3`,children:[(0,u.jsx)(`p`,{className:`text-[var(--text-secondary)] leading-relaxed`,style:{fontSize:`clamp(1.05rem, 1.25vw, 1.25rem)`,lineHeight:1.75},children:l.content[0]?.text}),(0,u.jsx)(`p`,{className:`text-[var(--text-secondary)] leading-relaxed`,style:{fontSize:`clamp(1.05rem, 1.25vw, 1.25rem)`,lineHeight:1.75},children:l.content[1]?.text})]})]}),r&&(0,u.jsx)(o,{verse:r})]}),(0,u.jsxs)(`section`,{id:`action`,className:`w-full max-w-[1000px] mx-auto space-y-6 flex flex-col items-center`,children:[(0,u.jsxs)(`div`,{className:`w-full p-8 sm:p-10 rounded-[20px] bg-[var(--surface)] border border-[var(--border-color)] shadow-sm text-center space-y-4`,children:[(0,u.jsx)(`span`,{className:`text-xs sm:text-sm uppercase tracking-widest text-[var(--saffron)] font-[var(--font-marginalia)] font-bold block`,children:`१.३ · कर्मण्यता`}),(0,u.jsx)(`h2`,{className:`font-[var(--font-heading-alt)] font-semibold text-[var(--text-primary)] text-balance mx-auto`,style:{fontSize:`clamp(1.75rem, 3.5vw, 2.75rem)`,lineHeight:1.2},children:`The 100-Year Life of Fearless Engagement`}),(0,u.jsx)(`div`,{className:`w-full max-w-[68ch] mx-auto text-left`,children:(0,u.jsx)(`p`,{className:`text-[var(--text-secondary)] leading-relaxed`,style:{fontSize:`clamp(1.05rem, 1.25vw, 1.25rem)`,lineHeight:1.75},children:`In verse 2, the seer proclaims that one should desire to live a hundred years performing actions without grasping. When you see all beings in the Self and the Self in all beings (verse 7), there is neither delusion nor grief.`})})]}),(0,u.jsxs)(`div`,{className:`w-full grid grid-cols-1 md:grid-cols-2 gap-6 my-6`,children:[i&&(0,u.jsx)(a,{verse:i}),h&&(0,u.jsx)(a,{verse:h})]})]}),(0,u.jsx)(`section`,{id:`vidya`,className:`w-full max-w-[1000px] mx-auto space-y-8 flex flex-col items-center`,children:(0,u.jsxs)(`div`,{className:`w-full p-8 sm:p-10 rounded-[20px] bg-[var(--surface)] border border-[var(--border-color)] shadow-sm text-center space-y-4`,children:[(0,u.jsx)(`span`,{className:`text-xs sm:text-sm uppercase tracking-widest text-[var(--gold)] font-[var(--font-marginalia)] font-bold block`,children:`१.४ · विद्या-अविद्या समन्वयः`}),(0,u.jsx)(`h2`,{className:`font-[var(--font-heading-alt)] font-semibold text-[var(--text-primary)] text-balance mx-auto`,style:{fontSize:`clamp(1.75rem, 3.5vw, 2.75rem)`,lineHeight:1.2},children:`The Two Wings of Resilience: Practical Competence & Transcendent Anchor`}),(0,u.jsx)(`div`,{className:`w-full max-w-[68ch] mx-auto text-left`,children:(0,u.jsx)(`p`,{className:`text-[var(--text-secondary)] leading-relaxed`,style:{fontSize:`clamp(1.05rem, 1.25vw, 1.25rem)`,lineHeight:1.75},children:`In verses 9–14, the Īśā issues its famous warning against extreme one-sidedness: those who pursue worldly mechanics (*avidyā*) alone enter blindness, but those who cling to transcendent abstraction (*vidyā*) enter greater darkness. True resilience integrates both: by empirical knowledge we navigate physical survival; by self-knowledge we realize immortality.`})})]})})]})}export{h as default};